            return null;
        }
        return backendList.substring(ALL_INSTANCES_PREFIX.length());
    }

    /**
     * 解析实例名称获取实例ID
     *
     * @param instanceName 实例名称
     * @return 实例ID
     */
    private static Optional<Integer> parseInstanceId(String instanceName) {
        try {
