            if (parts.length == 0) {
                LOGGER.warn("instanceName {} has no parts", instanceName);
                return Optional.empty();
            }
            String lastPart = parts[parts.length - 1];
            if (StringUtil.isEmpty(lastPart)) {
                LOGGER.warn("last part of instanceName {} is empty", instanceName);
                return Optional.empty();
            }
            int instanceId = Integer.parseInt(lastPart);
            LOGGER.info("parseInstanceId {} -> {}", instanceName, instanceId);
            return Optional.of(instanceId);
        } catch (NumberFormatException e) {
            LOGGER.warn("parseInstanceId {} failed, last part is not numeric", instanceName);
            return Optional.empty();
        }
    }
}
